// inline char * strcatz(char * out, char * in) - the
// mpstime.cpp:112 LOCAL body (distinct from the inline.h:42
// twin seated in MpstimeMain): append in at the NUL, then the
// 0x01 delimiter byte, then NUL.
internal fun strcatz(out: CharArray, inn: CharArray): CharArray {
    var p = 0
    while (p < out.size && out[p] != '\u0000') p++
    var q = 0
    while (q < inn.size && inn[q] != '\u0000') {
        out[p] = inn[q]
        p++
        q++
    }
    out[p] = '\u0001'
    p++
    if (p < out.size) out[p] = '\u0000'
    return out
}

